def transform(grid):
    h, w = len(grid), len(grid[0])
    canvas_cells = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 1]
    r0, r1 = min(r for r, c in canvas_cells), max(r for r, c in canvas_cells)
    c0, c1 = min(c for r, c in canvas_cells), max(c for r, c in canvas_cells)
    canvas = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    ch, cw = len(canvas), len(canvas[0])

    exterior = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and value != 1 and not (r0 <= r <= r1 and c0 <= c <= c1):
                exterior[value] = (r, c)
    points = list(exterior.items())
    minr = min(r for _, (r, _) in points)
    maxr = max(r for _, (r, _) in points)
    minc = min(c for _, (_, c) in points)
    maxc = max(c for _, (_, c) in points)
    corners = {}
    for color, (r, c) in points:
        corner = ('T' if r == minr else 'B') + ('L' if c == minc else 'R')
        corners[corner] = color

    if set(corners) == {'TL', 'TR', 'BR'}:
        out = [[canvas[ch - 1 - c][cw - 1 - r] for c in range(ch)] for r in range(cw)]
    elif set(corners) == {'TL', 'TR', 'BL'}:
        out = [list(row) for row in zip(*canvas)]
    else:  # bottom-right L: reflect vertically
        out = [row[:] for row in canvas[::-1]]

    marker_colors = set(corners.values())
    for row in out:
        for c, value in enumerate(row):
            if value in marker_colors:
                row[c] = 1
    oh, ow = len(out), len(out[0])
    target = {'TL': (1, 1), 'TR': (1, ow - 2), 'BL': (oh - 2, 1), 'BR': (oh - 2, ow - 2)}
    for corner, color in corners.items():
        r, c = target[corner]
        out[r][c] = color
    return out
